                nonlocal action_seq
                action_seq += 1
                detail = dict(detail)
                record = make_event_record(
                    "dom_event",
                    page_id,
                    event=event_name,
                    action_id=action_seq,
                    **detail,
                )
                page_actions.append(record)
                logger.log(record)

